import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
s=requests.Session(); s.headers.update({'x-api-key':key})
ids=['toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1','toolshed.g2.bx.psu.edu/repos/devteam/samtools_sort/samtools_sort/2.0.8','toolshed.g2.bx.psu.edu/repos/devteam/freebayes/freebayes/1.3.10+galaxy1','toolshed.g2.bx.psu.edu/repos/iuc/snpeff/snpEff/5.4+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/snpeff/snpEff_databases/5.4+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/bcftools_mpileup/bcftools_mpileup/1.24+galaxy0','toolshed.g2.bx.psu.edu/repos/iuc/bcftools_call/bcftools_call/1.24+galaxy0']
for tid in ids:
    r=s.get(url+'/api/tools/'+requests.utils.quote(tid,safe=''))
    print('\\n====',tid, r.status_code)
    obj=r.json()
    print('name',obj.get('name'),'version',obj.get('version'))
    print('inputs keys', list((obj.get('inputs') or {}).keys())[:30] if isinstance(obj.get('inputs'),dict) else type(obj.get('inputs')))
    def summarize(inp, prefix=''):
        if isinstance(inp, dict):
            for k,v in inp.items():
                if isinstance(v, dict):
                    typ=v.get('type') or v.get('model_class')
                    print(prefix+k, typ, 'label=',v.get('label'), 'optional=',v.get('optional'), 'value=',v.get('value'))
                    if 'inputs' in v and len(prefix)<20:
                        summarize(v['inputs'], prefix+k+'|')
                else: print(prefix+k, type(v))
        elif isinstance(inp, list):
            for v in inp[:20]:
                if isinstance(v,dict): print(prefix+v.get('name','?'), v.get('type'), 'label=',v.get('label'))
    summarize(obj.get('inputs'))
PY"

